ep({id:'C18-1',book:'CM',ch:18,n:1,part:CMn+' Chapter 18',title:'Rebar Before the Pour',
 blurb:'The ironworkers are done and the inspector is due. Grades, cover, spacing, ties, bends, field bending and welding.',
 scenes:[
 {who:'N',say:'The footing and wall rebar is tied. Luis walks the job with a tape before the inspection.',look:['reinforcement','cover','spacing']},
 {who:'L',say:'The tags say Grade 60.',
  ask:A('"Grade 60" reinforcement means:',['60% recycled steel','60 ksi minimum yield strength','No. 6 bars at 0 in','60 ksi ultimate strength'],1,'Ch. 18: the grade is the minimum yield strength in ksi.')},
 {who:'M',say:'The bars are a little rusty.',
  ask:A('Light rust on reinforcing bars:',['Is acceptable','Must be sandblasted off','Means rejection','Must be painted'],0,'Ch. 18: light rust is acceptable. Oil, grease and loose scale are not.')},
 {who:'N',say:'Now cover. The footing is cast directly against the earth.',look:['concrete cover'],
  ask:A('Minimum cover for concrete cast against and permanently exposed to earth:',['¾ in','1½ in','2 in','3 in'],3,'Table 18.13: 3 in. Formed concrete exposed to earth or weather: 2 in for No. 6 through No. 18 bars, 1½ in for No. 5 and smaller.')},
 {who:'L',say:'Inside the building, the slab bars sit ¾ inch from the bottom.',
  ask:A('Minimum cover for No. 11 and smaller bars in slabs not exposed to weather or ground:',['¾ in','1 in','1½ in','2 in'],0,'Table 18.13. Beams and columns with no exposure: 1½ in.')},
 {who:'M',say:'And the tolerance. Read the limit.',
  ask:A('The placing tolerance may never reduce the specified cover by more than:',['⅛ in','One-third of the specified cover','Half the cover','1 in'],1,'Table 18.11: minus ⅜ in (d ≤ 8 in) or minus ½ in (d > 8 in), but never more than one-third of the specified cover.')},
 {who:'N',say:'The column cages.',look:['ties','bends'],
  ask:A('Column ties may not be spaced farther apart than:',['8 bar diameters','16 longitudinal bar diameters (and 48 tie diameters and the least dimension)','24 in always','12 in'],1,'Table 18.7. Use No. 3 ties for No. 10 and smaller bars, and No. 4 for No. 11 and larger.')},
 {who:'L',say:'A bar is in the way. The ironworker wants to heat it with a torch and bend it.',
  ask:A('Bars partly embedded in concrete may be field-bent:',['Hot, always','Cold, unless heating is approved by the building official with the engineer\'s concurrence','Never','Only with a torch'],1,'18.4: heating to bend needs the building official\'s approval with the engineer\'s concurrence, and then the bar is heated and cooled slowly. Field bending can also reduce ductility (18.5).')},
 {who:'M',say:'One more: someone wants to weld a splice.',
  ask:A('Reinforcing bar intended for welding is ASTM ___, and welding follows ___:',['A615; AWS D1.1','A706; AWS D1.4','A36; AWS D1.4','A706; ACI 117'],1,'Ch. 18: A706 low-alloy bar (marked W). Welding follows AWS D1.4, with no tack welds at crossing bars.')},
 {who:'N',say:'Method recap: identify the member and its exposure, find the cover in Table 18.13, then read the tolerance, spacing and tie rules. The exposure decides the cover.'}],
 recap:[['Bar grades and weldable bar','Ch. 18','Ch. 18'],['Concrete cover','Table 18.13','Ch. 18'],['Placing tolerances','Table 18.11','Ch. 18'],['Bar spacing','Table 18.6','Ch. 18'],['Column ties','Table 18.7','Ch. 18'],['Bend diameters','Table 18.8','Ch. 18']],
 exam:['c123','c132','c122','c129','g044','a069','a084','a085','a086','c130','c131','g046','c125','c126','c127','c128','c124'],
 next:'Next time: a cold snap and a heat wave.'});

ep({id:'C19-1',book:'CM',ch:19,n:1,part:CMn+' Chapter 19',title:'Cold Snap and Heat Wave',
 blurb:'A Colorado week: snow on Monday and 95 °F by Friday. Placing temperatures, heaters, protection time and hot-weather precautions.',
 scenes:[
 {who:'N',say:'Monday. The forecast shows a daily average of 35 °F, and there is frost on the subgrade.',look:['cold weather concreting']},
 {who:'M',say:'Issue first: are we in cold-weather conditions?',
  ask:A('Cold-weather concreting conditions generally begin when the average daily temperature is at or below:',['32 °F','40 °F','50 °F','60 °F'],1,'19.3.')},
 {who:'L',say:'The subgrade is frozen, but the slab is only 6 inches thick...',
  ask:A('Concrete may be placed on a frozen subgrade:',['If the slab is thin','With an accelerator','Never','If covered right away'],2,'Ch. 19: never. Remove snow and ice first.')},
 {who:'M',say:'Read the placing temperature table. It depends on how thick the section is.',
  ask:A('Minimum placing temperature for a section less than 12 in thick:',['40 °F','45 °F','50 °F','55 °F'],3,'Table 19.2: less than 12 in, 55 °F; 12–36 in, 50 °F; 36–72 in, 45 °F; over 72 in, 40 °F.')},
 {who:'N',say:'The plant heats the water.',
  ask:A('Mixing water should not exceed what temperature when combined with the aggregates?',['120 °F','150 °F','175 °F','212 °F'],2,'19.4.')},
 {who:'L',say:'We tented the slab with propane heaters inside.',
  ask:A('Fuel-burning heaters inside enclosures must be vented because:',['They are loud','CO2 carbonates the fresh surface, leaving it soft and dusty','They raise the slump','Code says so for fire only'],1,'Ch. 19. Keep enclosures at least 1 ft from the concrete so air can circulate.')},
 {who:'M',say:'How long do we protect it, and how do we take the protection off?',
  ask:A('When protection is removed, the concrete temperature should not drop more than about:',['10 °F in 24 h','40 °F in 24 h','60 °F in 12 h','No limit'],1,'19.4. Protection is normally kept about 3 days, or about 2 days with an accelerator or Type III cement.')},
 {who:'L',say:'Can we add calcium chloride? The deck is galvanized metal.',
  ask:A('Calcium chloride must never be used in concrete placed on:',['Wood forms','Galvanized steel deck forms','Soil','Gravel'],1,'Ch. 19: also never in prestressed concrete, or where embedded aluminum is tied to steel.')},
 {who:'N',say:'Friday: 95 °F, low humidity and wind.',look:['hot weather concreting'],
  ask:A('In hot weather, the Manual says not to use:',['Retarders','Ice','Accelerators such as calcium chloride','Fog spray'],2,'Ch. 19. Hot-weather precautions start at about 80 °F. Ice must be fully melted before discharge. Lowering concrete temperature 1 °F takes about a 9 °F drop in cement, 4 °F in water or 2 °F in aggregate.')},
 {who:'N',say:'Method recap: identify the weather condition, find Chapter 19, and read the limits: placing temperature by section size, protection time and what never to do.'}],
 recap:[['Cold-weather definition','19.3','Ch. 19'],['Placing temperatures by section size','Table 19.2','Ch. 19'],['Heating water and materials','19.4','Ch. 19'],['Protection time and removal','19.4','Ch. 19'],['Calcium chloride limits','Ch. 19','Ch. 19'],['Hot-weather precautions','Ch. 19','Ch. 19']],
 exam:['g048','c144','g049','c138','c139','g050','c140','c141','c143','g051','c142','c134','c135','c136','c137'],
 next:'Next time: the slab on ground, from subgrade to joints.'});

