G11.Q.push(
 Tq('t121','I1-2',1,'Under §110.1, whose duty is it to keep permitted work visible and able to be accessed for inspection until approved?',['The building official','The owner or the owner\'s authorized agent','The jurisdiction','The material supplier'],1,'§110.1: the owner or the owner\'s authorized agent. Neither the building official nor the jurisdiction is liable for the cost of removing or replacing material to allow inspection.',['The official inspects; the duty to keep it accessible is the owner\'s.',null,'The jurisdiction is not liable for removal costs.','No duty under §110.1.'],'§110.1','8','Section 110 Inspections, page 8.'),
 Tq('t122','I1-2',1,'Who must notify the building official that work is ready for inspection?',['The building official\'s staff','The holder of the building permit or their authorized agent','The neighbor','The design professional only'],1,'§110.5 Inspection requests: the permit holder or their duly authorized agent, who must also provide access to the work.',['They respond to requests.',null,'No role.','Not required by §110.5.'],'§110.5','9','§110.5, page 9.'),
 Tq('t123','I1-2',2,'An inspection finds part of the work does not comply. Under §110.6, that portion:',['May be covered if the rest passed','Must be corrected and not covered or concealed until authorized by the building official','Is approved by default after 48 hours','Requires a new permit'],1,'§110.6 Approval required: work does not go beyond the point of each successive inspection without approval; noncomplying portions are corrected and not covered until authorized.',['Not permitted.',null,'No such rule.','Not stated.'],'§110.6','9','§110.6, page 9.'),
 Tq('t124','I1-3',2,'The board of appeals hears an appeal of the building official\'s decision. Under §113.2, the board:',['May waive any code requirement','Has no authority to waive requirements of the code','May waive fees only','May issue permits'],1,'§113.2 Limitations on authority: an appeal is based on a claim that the code was incorrectly interpreted, does not fully apply, or that an equally good or better form of construction is proposed. The board may not waive code requirements.',['Not permitted.',null,'Not in §113.2.','Permits come from the building official.'],'§113.2','10','Section 113 Board of appeals, page 10.'),
 Tq('t125','I1-3',1,'Under §115.2, a stop work order is:',['Given verbally only','In writing, given to the owner, the owner\'s agent or the person doing the work','Posted online only','Issued by the contractor'],1,'§115.2 Issuance: the order is in writing and states the reason and the conditions under which work may resume.',['It is in writing.',null,'Not stated.','The building official issues it (§115.1).'],'§115.2','10','§115.2, page 10.')
);
